import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Regiones incapacitadas y uso del escudo","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/disability.md","filePath":"es/game-design/combat/disability.md"}'),s={name:"es/game-design/combat/disability.md"};function d(c,e,t,r,l,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="disabled-regions-and-shield-use" tabindex="-1">Regiones incapacitadas y uso del escudo <a class="header-anchor" href="#disabled-regions-and-shield-use" aria-label="Enlace permanente a &quot;Regiones incapacitadas y uso del escudo&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la consecuencia y las políticas experimentales de lado/fallo. Implementación: transiciones de integridad/condición en vivo de Stage 2A; sin comportamiento del escudo.</strong></p><p>Disabled significa pérdida de función, no amputación automática ni condición de muerte independiente. Cuando el brazo que sostiene el escudo llega a Disabled, ese mismo escudo en propiedad pasa a la mochila, nunca al suelo, y se bloquea su reequipamiento mientras el brazo siga Disabled. Las reglas ordinarias de muerte y botín posteriores siguen aplicándose.</p><p>Slice 0 usa la convención experimental aprobada de <code>LeftArm</code> como brazo de apoyo. La capa de equipo <code>TwoHanded</code> no representa lateralidad anatómica. Otras regiones a cero en este primer slice no causan muerte extra, ralentización de movimiento, penalización de precisión ni caída del arma. Un RightArm incapacitado no debe activar por accidente la regla provisional del escudo en LeftArm.</p><p>La excepción de capacidad con mochila llena y la exclusión de mochilas ausentes/eliminadas/personalizadas son políticas de prototipo con estado Aceptado; no son un diseño de inventario permanente. Detener la implementación afectada si no puede preservarse la propiedad.</p><p>La recuperación no reequipa automáticamente el escudo. El contrato técnico de guardado del escudo especifica las transiciones y el comportamiento peligroso de funciones auxiliares heredadas. <strong>Carencia:</strong> Stage 2A se detiene deliberadamente en la etapa intermedia documentada de acumulación. Disabled es observable, pero la reubicación del escudo/restricciones de equipamiento y todas las demás penalizaciones funcionales están aplazadas. La reubicación segura y todas las vías de equipamiento requieren implementación y comprobaciones posteriores en ejecución.</p>',6)])])}const g=a(s,[["render",d]]);export{u as __pageData,g as default};
